const items = $input.all();

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// =====================================================
// JOB DATA FROM GOOGLE SHEETS
// =====================================================

const jobs = items
  .map(item => item.json)
  .filter(job =>
    job['Job Title'] ||
    job['Company'] ||
    job['URL']
  );

const totalJobs = jobs.length;

const suitableJobs = jobs.filter(job =>
  String(job['AI Decision'] || '').toUpperCase() === 'SUITABLE'
);

const applications = suitableJobs.filter(job =>
  String(job['Application'] || '').trim() !== ''
).length;

// =====================================================
// JOB CARDS
// =====================================================

const jobCards = suitableJobs.length
  ? suitableJobs.map(job => {

      const title =
        escapeHtml(job['Job Title'] || 'Untitled Job');

      const company =
        escapeHtml(job['Company'] || 'Unknown Company');

      const location =
        escapeHtml(
          job['Location'] || 'Location not specified'
        );

      const jobType =
        job['Job Type']
          ? '<span>' +
            escapeHtml(job['Job Type']) +
            '</span>'
          : '';

      const category =
        job['Category']
          ? '<span>' +
            escapeHtml(job['Category']) +
            '</span>'
          : '';

      const applyButton =
        job['URL']
          ? '<a class="apply-button" href="' +
            escapeHtml(job['URL']) +
            '" target="_blank" rel="noopener noreferrer">' +
            'Apply' +
            '</a>'
          : '';

      return (
        '<div class="job">' +

          '<h3>' +
            title +
          '</h3>' +

          '<div class="company">' +
            company +
          '</div>' +

          '<div class="details">' +

            '<span>' +
              location +
            '</span>' +

            jobType +

            category +

          '</div>' +

          '<div class="job-actions">' +

            '<span class="status">' +
              'SUITABLE' +
            '</span>' +

            applyButton +

          '</div>' +

        '</div>'
      );

    }).join('')
  : (
      '<div class="job">' +

        '<h3>No suitable jobs found</h3>' +

        '<div class="company">' +
          'Run the job search to find suitable opportunities.' +
        '</div>' +

      '</div>'
    );

// =====================================================
// COMPLETE HTML
