<div id="app"></div>

<script>

/* =================================================
   CONFIGURATION
================================================= */

const SAVE_PROFILE_URL =
  '[N8N_WEBHOOK_URL_REDACTED]';

const JOB_SEARCH_URL =
  '[N8N_WEBHOOK_URL_REDACTED]';

const STATUS_URL =
  '[N8N_WEBHOOK_URL_REDACTED]';


/* =================================================
   URL PARAMETERS
================================================= */

const params =
  new URLSearchParams(window.location.search);

const page =
  params.get('page');

const profileId =
  params.get('profileId');


/* =================================================
   PAGE 1 — CREATE PROFILE
================================================= */

function showProfilePage() {

  const app =
    document.getElementById('app');

  app.innerHTML =
    '<div class="profile-page">' +

      '<h1>' +
        'Create Your Job Profile' +
      '</h1>' +

      '<div class="subtitle">' +
        'Tell AI Job Hunter about yourself so it can find jobs that match your profile.' +
      '</div>' +

      '<div class="profile">' +

        '<h2>' +
          '👤 Candidate Details' +
        '</h2>' +

        '<div class="form-grid">' +

          '<div class="form-group">' +

            '<label>' +
              'Country' +
            '</label>' +

            '<input ' +
              'id="country" ' +
              'type="text" ' +
              'placeholder="e.g. Pakistan"' +
            '>' +

          '</div>' +


          '<div class="form-group">' +

            '<label>' +
              'Experience Level' +
            '</label>' +

            '<select id="experience">' +

              '<option value="Fresh Graduate">' +
                'Fresh Graduate' +
              '</option>' +

              '<option value="0-2 Years">' +
                '0–2 Years' +
              '</option>' +

              '<option value="2-5 Years">' +
                '2–5 Years' +
              '</option>' +

              '<option value="5+ Years">' +
                '5+ Years' +
              '</option>' +

            '</select>' +

          '</div>' +


          '<div class="form-group full">' +

            '<label>' +
              'Skills' +
            '</label>' +

            '<textarea ' +
              'id="skills" ' +
              'placeholder="e.g. Python, Machine Learning, AI, LLMs, RAG"' +
            '></textarea>' +

          '</div>' +


          '<div class="form-group full">' +

            '<label>' +
              'Desired Roles' +
            '</label>' +

            '<textarea ' +
              'id="roles" ' +
              'placeholder="e.g. AI Engineer, Python Developer, ML Engineer"' +
            '></textarea>' +

          '</div>' +


          '<div class="form-group full">' +

            '<label>' +
              'Work Preference' +
            '</label>' +

            '<div class="checkbox-group">' +

              '<label class="checkbox-item">' +

                '<input ' +
                  'type="checkbox" ' +
                  'id="remote"' +
                '>' +

                'Remote' +

              '</label>' +


              '<label class="checkbox-item">' +

                '<input ' +
                  'type="checkbox" ' +
                  'id="hybrid"' +
                '>' +

                'Hybrid' +

              '</label>' +


              '<label class="checkbox-item">' +

                '<input ' +
                  'type="checkbox" ' +
                  'id="onsite"' +
                '>' +

                'On-site' +

              '</label>' +

            '</div>' +

          '</div>' +

        '</div>' +


        '<button ' +
          'class="save-profile" ' +
          'onclick="saveProfile()"' +
        '>' +

          '💾 Save & Continue' +

        '</button>' +


        '<div ' +
          'id="profileStatus" ' +
          'class="profile-status"' +
        '></div>' +

      '</div>' +

    '</div>';

}


/* =================================================
   SAVE PROFILE
================================================= */

async function saveProfile() {

  const status =
    document.getElementById('profileStatus');

  const button =
    document.querySelector('.save-profile');


  const profile = {

    profileId:
      'user-' + Date.now(),

    country:
      document.getElementById('country')
        .value
        .trim(),

    experience:
      document.getElementById('experience')
        .value,

    skills:
      document.getElementById('skills')
        .value
        .trim(),

    roles:
      document.getElementById('roles')
        .value
        .trim(),

    workPreference: [

      document.getElementById('remote').checked
        ? 'Remote'
        : null,

      document.getElementById('hybrid').checked
        ? 'Hybrid'
        : null,

      document.getElementById('onsite').checked
        ? 'On-site'
        : null

    ]
      .filter(Boolean)
      .join(', ')

  };


  if (
    !profile.country ||
    !profile.skills ||
    !profile.roles
  ) {

    status.textContent =
      '⚠️ Please fill in Country, Skills and Desired Roles.';

    return;

  }


  button.disabled =
    true;

  button.textContent =
    '⏳ Saving...';


  status.textContent =
    '';


  try {

    const response =
      await fetch(
        SAVE_PROFILE_URL,
        {

          method: 'POST',

          headers: {
            'Content-Type':
              'application/json'
          },

          body:
            JSON.stringify(profile)

        }
      );


    if (!response.ok) {

      throw new Error(
        'Profile could not be saved.'
      );

    }


    status.textContent =
      '✅ Profile saved successfully!';


    setTimeout(function() {

      window.location.href =
        '?page=dashboard&profileId=' +
        encodeURIComponent(
          profile.profileId
        );

    }, 500);


  } catch (error) {

    console.error(error);

    button.disabled =
      false;

    button.textContent =
      '💾 Save & Continue';

    status.textContent =
      '❌ Could not save profile. Please try again.';

  }

}


/* =================================================
   PAGE 2 — DASHBOARD
================================================= */

function showDashboardPage() {

  const app =
    document.getElementById('app');

  app.innerHTML =
    '<div class="container">' +

      '<h1>' +
        '🤖 AI Job Hunter' +
      '</h1>' +

      '<div class="subtitle">' +
        'Automated job discovery, AI screening and application assistance' +
      '</div>' +


      '<div class="dashboard">' +

        '<div class="card">' +

          '<div>' +
            'Total Jobs' +
          '</div>' +

          '<div class="number">' +
            '${totalJobs}' +
          '</div>' +

        '</div>' +


        '<div class="card">' +

          '<div>' +
            'Suitable Jobs' +
          '</div>' +

          '<div class="number">' +
            '${suitableJobs.length}' +
          '</div>' +

        '</div>' +


        '<div class="card">' +

          '<div>' +
            'Applications' +
          '</div>' +

          '<div class="number">' +
            '${applications}' +
          '</div>' +

        '</div>' +

      '</div>' +


      '<button ' +
        'class="button" ' +
        'onclick="runJobSearch()"' +
      '>' +

        '🔍 Run Job Search' +

      '</button>' +


      '<div class="jobs">' +

        '<h2>' +
          'Suitable Jobs' +
        '</h2>' +

        '${jobCards}' +

      '</div>' +

    '</div>';

}

 let searchStartedAt = 0;
/* =================================================
   RUN JOB SEARCH
================================================= */

async function runJobSearch() {

  const button =
    document.querySelector('.button');


  if (!profileId) {

    alert(
      'Profile ID is missing. Please create your profile again.'
    );

    return;

  }

const searchId =
  'search-' + Date.now();

searchStartedAt = Date.now();

button.disabled =
  true;

  button.textContent =
    '⏳ Searching...';


  try {

    const searchUrl =
      JOB_SEARCH_URL +
      '?profileId=' +
      encodeURIComponent(profileId) +
      '&searchId=' +
      encodeURIComponent(searchId);


    await fetch(
      searchUrl,
      {
        method: 'GET',
        mode: 'no-cors'
      }
    );


    button.textContent =
      '🔄 Search running...';


    checkSearchStatus(
      searchId,
      button
    );


  } catch (error) {

    console.error(error);

    button.disabled =
      false;

    button.textContent =
      '❌ Failed — Try Again';

  }

}


/* =================================================
   CHECK BACKEND SEARCH STATUS
================================================= */

async function checkSearchStatus(
  searchId,
  button
) {

  try {

    const response =
      await fetch(
        STATUS_URL +
        '?searchId=' +
        encodeURIComponent(searchId)
      );


    const data =
      await response.json();


    const currentStatus =
      String(
        data.Status || ''
      ).toUpperCase();

    const elapsedTime =
  Date.now() - searchStartedAt;

if (elapsedTime > 10 * 60 * 1000) {
  button.disabled = false;
  button.textContent = '🔍 Run Job Search';

  alert('Search timed out. The workflow may have stopped with an error.');

  return;
}


    if (
  currentStatus === 'COMPLETED'
) {

  button.disabled = false;
  button.textContent = '🔍 Run Job Search';

  window.location.reload();

  return;
}

if (
  currentStatus === 'FAILED'
) {

  button.disabled = false;
  button.textContent = '🔍 Run Job Search';

  let errorMessage =
    document.getElementById('searchError');

  if (!errorMessage) {
    errorMessage =
      document.createElement('div');

    errorMessage.id =
      'searchError';

    errorMessage.style.color =
      '#dc2626';

    errorMessage.style.fontWeight =
      '600';

    errorMessage.style.marginTop =
      '10px';

    button.parentElement.appendChild(
      errorMessage
    );
  }

  errorMessage.textContent =
    '⚠️ Job Search Failed';

  return;
}

if (!currentStatus) {
  button.disabled = false;
  button.textContent = '🔍 Run Job Search';
  alert('Search status could not be found.');
  return;
}

    setTimeout(
      function() {

        checkSearchStatus(
          searchId,
          button
        );

      },
      5000
    );


  } catch (error) {

    console.error(
      'Status check failed:',
      error
    );


    setTimeout(
      function() {

        checkSearchStatus(
          searchId,
          button
        );

      },
      5000
    );

  }

}


/* =================================================
   START CORRECT PAGE
================================================= */

if (
  page === 'dashboard' &&
  profileId
) {

  showDashboardPage();

} else {

  showProfilePage();

}

</script>

</body>

</html>
